package exam; public class Admission { public enum Status {NEW,VERIFIED,REVOKED} public final String id,detail; private Status status; public Admission(String id,String detail,Status status){this.id=id;this.detail=detail;this.status=status;} public Status status(){return status;} public void verify(){if(status!=Status.NEW)throw new IllegalStateException("Illegal transition "+status);status=Status.VERIFIED;} public void revoke(){if(status!=Status.VERIFIED)throw new IllegalStateException("Illegal transition "+status);status=Status.REVOKED;}}
